/// <summary>
/// Contract class for Rebate Accrual Process
/// CB748_RebateAccrualProcess
/// </summary>
internal final class METRebateAccrualContract extends METSysOperationTaskDataContract
{
    guid                       topPickingProcessId;

}

Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// Provides thread count parameter
/// </summary>
/// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
/// <returns>The thread count</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;

    return threadCount;
}
